package com.campusconnect.dao;
import com.campusconnect.exception.DatabaseException; import com.campusconnect.model.Claim; import com.campusconnect.util.DatabaseConnection; import java.sql.*; import java.util.*;
public class ClaimDAO { private Claim map(ResultSet r)throws SQLException{Claim x=new Claim();x.setId(r.getInt("id"));x.setItemId(r.getInt("item_id"));x.setStudentId(r.getInt("student_id"));x.setItemTitle(r.getString("item_title"));x.setStudentName(r.getString("student_name"));x.setStatus(r.getString("status"));x.setCreatedAt(r.getTimestamp("created_at").toLocalDateTime());return x;}
 public List<Claim> findAll(){return query(0);} public List<Claim> findByStudent(int id){return query(id);} private List<Claim> query(int id){List<Claim>a=new ArrayList<>();String w=id==0?"":"WHERE c.student_id=?";String sql="SELECT c.*,l.title item_title,s.name student_name FROM claims c JOIN lost_found_items l ON l.id=c.item_id JOIN students s ON s.user_id=c.student_id "+w+" ORDER BY c.created_at DESC";try(Connection c=DatabaseConnection.getConnection();PreparedStatement p=c.prepareStatement(sql)){if(id!=0)p.setInt(1,id);try(ResultSet r=p.executeQuery()){while(r.next())a.add(map(r));}}catch(SQLException e){throw new DatabaseException("Could not load claims.",e);}return a;}
 public void insert(int itemId,int studentId){try(Connection c=DatabaseConnection.getConnection();PreparedStatement p=c.prepareStatement("INSERT INTO claims(item_id,student_id,status) VALUES(?,?, 'Pending')")){p.setInt(1,itemId);p.setInt(2,studentId);p.executeUpdate();}catch(SQLException e){throw new DatabaseException("Could not submit claim. A claim may already exist.",e);}}
 public void updateStatus(int id,String status){try(Connection c=DatabaseConnection.getConnection();PreparedStatement p=c.prepareStatement("UPDATE claims SET status=? WHERE id=?")){p.setString(1,status);p.setInt(2,id);p.executeUpdate();}catch(SQLException e){throw new DatabaseException("Could not update claim.",e);}}
}
